from functools import lru_cache
from typing import Callable, Hashable, Iterable, TypeVar

Position = TypeVar("Position", bound=Hashable)

def value_function(moves: Callable[[Position], Iterable[Position]]) -> Callable[[Position], bool]:
    """W(p) = True iff the player to move at p wins, via the Zermelo fixed point
    W(p) <-> exists q in moves(p) with not W(q). Well-foundedness ensures termination."""
    @lru_cache(maxsize=None)
    def W(p: Position) -> bool:
        return any(not W(q) for q in moves(p))
    return W

if __name__ == "__main__":
    # Countdown on N: from a move to any b < a; 0 is terminal.
    W = value_function(lambda a: range(a))
    for n in range(8):
        print(f"W({n}) = {W(n)}   (closed form n != 0 -> {n != 0})")

from functools import lru_cache
from typing import Callable, Hashable, Iterable, List, Optional, TypeVar

Position = TypeVar("Position", bound=Hashable)

def value_function(moves: Callable[[Position], Iterable[Position]]) -> Callable[[Position], bool]:
    @lru_cache(maxsize=None)
    def W(p: Position) -> bool:
        return any(not W(q) for q in moves(p))
    return W

def optimal_move(moves, W, p):
    if not W(p):
        return None
    for q in moves(p):
        if not W(q):
            return q
    return None

def is_terminal(moves, p) -> bool:
    for _ in moves(p):
        return False
    return True

def play(moves, W, start, opponent) -> List:
    """Run the game: analysed player plays greedily at winning positions,
    opponent moves at losing positions. Returns the trajectory."""
    traj, p = [start], start
    while not is_terminal(moves, p):
        p = optimal_move(moves, W, p) if W(p) else opponent(p)
        traj.append(p)
    return traj

if __name__ == "__main__":
    moves = lambda a: range(a)              # countdown on N
    W = value_function(moves)
    opp = lambda p: next(iter(moves(p)))    # opponent: move to smallest option
    for start in (7, 4, 1):
        t = play(moves, W, start, opp)
        turn = len(t) - 1
        print(f"start {start}: {t}  terminal turn {turn} "
              f"({'odd, mover wins' if turn % 2 else 'even, mover loses'})")

from functools import lru_cache
from typing import Callable, Hashable, Iterable, TypeVar

Position = TypeVar("Position", bound=Hashable)

def grundy_value(moves: Callable[[Position], Iterable[Position]]) -> Callable[[Position], int]:
    """Sprague-Grundy refinement of the Boolean value: g(p) = mex{ g(q) : p -> q }.
    A position is losing for the mover iff g(p) == 0, recovering W(p) = (g(p) != 0)."""
    @lru_cache(maxsize=None)
    def g(p: Position) -> int:
        reachable = {g(q) for q in moves(p)}
        m = 0
        while m in reachable:
            m += 1
        return m
    return g

if __name__ == "__main__":
    # Subtraction game: remove 1, 2, or 3 tokens.
    moves = lambda n: (n - k for k in (1, 2, 3) if k <= n)
    g = grundy_value(moves)
    for n in range(13):
        print(f"g({n}) = {g(n)}   losing(mover)={g(n) == 0}   (n % 4 == 0 -> {n % 4 == 0})")

