from functools import lru_cache
from typing import Callable, Hashable, Iterable, List, Optional, TypeVar

Position = TypeVar("Position", bound=Hashable)

def canonical_play(moves: Callable[[Position], Iterable[Position]],
                   start: Position,
                   opponent: Callable[[Position], Position]) -> List[Position]:
    """Play the game from `start`, the analysed player using the canonical
    greedy strategy and the opponent using an arbitrary legal strategy.

    Returns the trajectory up to (and including) the first terminal position.
    Terminates because every play in a well-founded game is finite."""
    @lru_cache(maxsize=None)
    def W(q: Position) -> bool:
        return any(not W(r) for r in moves(q))

    def opt(q: Position) -> Optional[Position]:
        return next((r for r in moves(q) if not W(r)), None)

    def terminal(q: Position) -> bool:
        return next(iter(moves(q)), None) is None

    traj: List[Position] = [start]
    p = start
    while not terminal(p):
        p = opt(p) if W(p) else opponent(p)  # type: ignore[assignment]
        traj.append(p)
    return traj

