from functools import lru_cache
from typing import Callable, Hashable, Iterable, TypeVar

Position = TypeVar("Position", bound=Hashable)

def grundy(moves: Callable[[Position], Iterable[Position]],
           p: Position) -> int:
    """Sprague-Grundy value g(p) = mex{ g(q) : p -> q }.

    The minimal excludant (mex) of a set S of naturals is the least natural
    not in S. Losing positions for the mover are exactly those with g(p) = 0,
    so g refines the Boolean value: W(p) <-> g(p) != 0."""
    @lru_cache(maxsize=None)
    def g(q: Position) -> int:
        seen = {g(r) for r in moves(q)}
        m = 0
        while m in seen:
            m += 1
        return m
    return g(p)
